import{b as n,j as t,F as r}from"./three-92ffd73b.js";const s=[{id:"why-my-old-systems-kept-rotting",text:"Why my old systems kept rotting",depth:2},{id:"my-actual-structure",text:"My actual structure",depth:2},{id:"why-it-sticks",text:"Why it sticks",depth:2},{id:"daily-notes-and-quick-capture",text:"Daily notes and quick capture",depth:2},{id:"how-trips-work",text:"How trips work",depth:2},{id:"the-stuff-that-doesnt-fit",text:"The stuff that doesn't fit",depth:2},{id:"if-you-want-to-try-it",text:"If you want to try it",depth:2}];function a(i){const e={a:"a",code:"code",em:"em",h2:"h2",p:"p",pre:"pre",span:"span",...i.components};return t(r,{children:[n(e.p,{children:'I used to have notes everywhere. Google Docs for work, Apple Notes for random thoughts, Notion for projects I never finished, and a graveyard of markdown files in folders called "misc" and "to-sort-later." Finding anything meant searching three apps and trying to remember which one past me had picked that day.'}),`
`,n(e.p,{children:`A couple of years ago I moved everything into Obsidian. One app helped. One app full of the same chaos did not. I had a flat pile of files with no structure, and I'd write a note, give it a perfectly reasonable name, and never find it again, because was it "Jordan trip" or "2024 travel plans" or just "vacation"?`}),`
`,t(e.p,{children:["Then I found ",n(e.a,{href:"https://johnnydecimal.com",children:"Johnny Decimal"}),"."]}),`
`,t(e.h2,{id:"why-my-old-systems-kept-rotting",children:[n(e.a,{"aria-hidden":"true",tabIndex:"-1",href:"#why-my-old-systems-kept-rotting",children:n(e.span,{className:"icon icon-link"})}),"Why my old systems kept rotting"]}),`
`,n(e.p,{children:`Every system I'd tried was too flexible. Unlimited folders, nested however I liked, named whatever felt right in the moment. Six months later I'd have "Work" and "Professional" and "Career" all holding different things, and "Travel" would be inside "Personal" inside "Life," unless it was floating at the root next to "2023 stuff."`}),`
`,n(e.p,{children:"Johnny Decimal takes that freedom away. You get 10 areas (numbered 00-09 through 90-99), and each area gets 10 categories. A hundred buckets, total, for everything you will ever want to file."}),`
`,n(e.p,{children:`My first reaction was that 100 couldn't possibly be enough. It felt almost insulting. Then I tried listing everything I actually care about, and most of my old "organization" turned out to be the same handful of things wearing different names.`}),`
`,t(e.h2,{id:"my-actual-structure",children:[n(e.a,{"aria-hidden":"true",tabIndex:"-1",href:"#my-actual-structure",children:n(e.span,{className:"icon icon-link"})}),"My actual structure"]}),`
`,n(e.p,{children:"This is the vault as it stands:"}),`
`,n(e.pre,{children:n(e.code,{children:`00-09 System/
├── 00 System Management
├── 01 Daily Notes
└── 02 Research
10-19 Tech/
├── 11 Code
├── 12 Homelab
├── 13 Projects
├── 14 Internet & Websites
└── 15 AI
20-29 Travel/
├── 21 Perks & Discounts
├── 22 Trips
└── 23 Travel Resources
30-39 Personal/
├── 31 Career
├── 32 Finance
├── 33 Living
├── 34 Health & Style
├── 35 Entertainment
├── 36 Food
├── 37 Personal Development
├── 38 Speeches & Writing
└── 39 Content
`})}),`
`,t(e.p,{children:[n(e.code,{children:"00-09 System"})," is the notes about notes: the inbox where quick captures land before I sort them, templates, daily notes, and research that hasn't earned a home yet. It's a junk drawer, but a junk drawer with a label on it."]}),`
`,t(e.p,{children:[n(e.code,{children:"10-19 Tech"})," is my technical life. Code references I keep looking up, homelab documentation, active projects, AI prompts and tools. Anything that would look at home on a developer's desk."]}),`
`,t(e.p,{children:[n(e.code,{children:"20-29 Travel"})," holds more than you'd expect. Every trip gets a folder with the research, the booking info, and a trip report afterwards. Loyalty programs and perks get their own category, and so do packing lists and general resources. When I was planning Jordan I knew where to look, and when I got back I knew where the notes went."]}),`
`,t(e.p,{children:[n(e.code,{children:"30-39 Personal"})," is everything else in my life. Resumes and interview prep under Career. Tax documents and account info under Finance. Living arrangements, health records, reading lists and things to watch, recipes, personal development, writing projects, content ideas."]}),`
`,n(e.p,{children:"Four areas. I don't use 40-99 and maybe never will. The system doesn't mind gaps."}),`
`,t(e.h2,{id:"why-it-sticks",children:[n(e.a,{"aria-hidden":"true",tabIndex:"-1",href:"#why-it-sticks",children:n(e.span,{className:"icon icon-link"})}),"Why it sticks"]}),`
`,n(e.p,{children:"The numbers are nice, but what actually does the work is the ceiling. Ten areas, ten categories, no exceptions, which means there are very few places anything can go."}),`
`,t(e.p,{children:["When I save a note about the Turkish baths in Petra, I don't wonder where it belongs. Travel, so ",n(e.code,{children:"20-29 Travel"}),". Then ",n(e.code,{children:"22.01 Trips"}),", then Jordan. There's nowhere else it ",n(e.em,{children:"could"})," go, and I know the path before the file exists."]}),`
`,t(e.p,{children:["When I want my brother's wedding speech, I don't search. ",n(e.code,{children:"30-39 Personal"}),", then ",n(e.code,{children:"38.01 Speeches & Writing"}),", and there it is."]}),`
`,t(e.p,{children:["Every piece of information ends up with an address. ",n(e.code,{children:"32.01"})," means Finance within Personal, and the ",n(e.code,{children:".01"}),' points at a specific document or subfolder. If someone asks where I keep tax documents, the answer is "',n(e.code,{children:"32.01 Finance"}),', Tax Documents folder," which beats "somewhere in my notes" by a wide margin.']}),`
`,t(e.p,{children:["Try it with my structure. Your building has just emailed about changes to your rental agreement and you want to keep it. It's personal, so ",n(e.code,{children:"30-39 Personal"}),". It's about where you live, so ",n(e.code,{children:"33 Living"}),". Call it ",n(e.code,{children:"rental_agreement_2026.pdf"})," and you're finished."]}),`
`,t(e.p,{children:["You could go deeper, something like ",n(e.code,{children:"33.01 Living/10 Yearly Rentals/2026/<file>.pdf"}),". I can do that inside any drawer whenever I like. The drawers only have to get everything into a state where it ",n(e.em,{children:"can"})," be organized."]}),`
`,t(e.p,{children:["Same with a recipe you find online. Personal, Food, ",n(e.code,{children:"36 Food"}),". Maybe one day ",n(e.code,{children:"36 Food"})," grows subfolders for cuisines or meal types. Maybe it never does. Either way, recipes live in one place."]}),`
`,t(e.h2,{id:"daily-notes-and-quick-capture",children:[n(e.a,{"aria-hidden":"true",tabIndex:"-1",href:"#daily-notes-and-quick-capture",children:n(e.span,{className:"icon icon-link"})}),"Daily notes and quick capture"]}),`
`,t(e.p,{children:["Most of my time in Obsidian is spent in daily notes. Every morning a new file shows up in ",n(e.code,{children:"00-09 System"})," / ",n(e.code,{children:"01.01 Daily Notes"}),", named with the date, built from the same template every time:"]}),`
`,n(e.pre,{children:t(e.code,{className:"hljs language-markdown",children:[n(e.span,{className:"hljs-section",children:"# 2025-01-03"}),`

`,n(e.span,{className:"hljs-section",children:"## Tasks"}),`

`,n(e.span,{className:"hljs-bullet",children:"-"}),` [ ] Review PR for auth refactor
`,n(e.span,{className:"hljs-bullet",children:"-"}),` [ ] Update API docs for v2 endpoints
`,n(e.span,{className:"hljs-bullet",children:"-"}),` [x] Fix flaky integration test
`,n(e.span,{className:"hljs-bullet",children:"-"}),` [ ] Schedule 1:1 with manager

`,n(e.span,{className:"hljs-section",children:"## Notes"}),`
`]})}),`
`,n(e.p,{children:"Two sections. Tasks is what I need to do today, and Notes is everything else that turns up."}),`
`,t(e.p,{children:["During the day I throw things into Notes: half-ideas, things to look up, links people send me. At the end of the day or the week I move anything worth keeping to its proper home. The rental agreement reminder goes to ",n(e.code,{children:"33.01 Living"}),", the recipe link to ",n(e.code,{children:"36.01 Food"}),". Most of it just gets deleted, which is the point. The daily note is a holding pen. Capture fast, sort later, and let most of it die."]}),`
`,t(e.h2,{id:"how-trips-work",children:[n(e.a,{"aria-hidden":"true",tabIndex:"-1",href:"#how-trips-work",children:n(e.span,{className:"icon icon-link"})}),"How trips work"]}),`
`,n(e.p,{children:"Trip planning used to overwhelm me. Research lived in browser tabs and stray notes, confirmations were buried in email, and the itinerary was… somewhere."}),`
`,t(e.p,{children:["Now every trip gets a folder under ",n(e.code,{children:"22.01 Trips"}),". Before I leave it fills up with research: restaurant recommendations, things to see, logistics like visa requirements and local emergency contacts, booking numbers and hotel addresses."]}),`
`,n(e.p,{children:"When I get back I write a trip report. Not a polished travel blog. Practical notes about what I actually did each day, what worked, what didn't, what things cost, and everything I wish I'd known before I went."}),`
`,n(e.p,{children:`My Jordan report has lines like "Uber from airport is 30 JOD to downtown" and "don't wash your face in the Dead Sea, the salt will wreck your eyes" and "the monastery hike from Little Petra takes a couple hours and you descend 9000+ steps at the end." A year later, when a friend asks about Jordan, I send them the file.`}),`
`,t(e.h2,{id:"the-stuff-that-doesnt-fit",children:[n(e.a,{"aria-hidden":"true",tabIndex:"-1",href:"#the-stuff-that-doesnt-fit",children:n(e.span,{className:"icon icon-link"})}),"The stuff that doesn't fit"]}),`
`,n(e.p,{children:"Some things refuse to be categorized. Research that spans several areas. Ideas too unformed to place. Things I'm actively chewing on but haven't decided what they are yet."}),`
`,t(e.p,{children:["Those go in the System area: ",n(e.code,{children:"02.01 Research"})," for deep dives, the inbox for quick captures, daily notes for anything transient. I didn't expect the structure to have room for ambiguity, but it does."]}),`
`,n(e.p,{children:`It isn't perfect. I still put a note in the wrong spot and notice a week later. I've spent an absurd amount of time deciding whether something is "Career" or "Personal Development." The system doesn't kill decision fatigue. It just makes most decisions boring enough that they happen on their own.`}),`
`,t(e.h2,{id:"if-you-want-to-try-it",children:[n(e.a,{"aria-hidden":"true",tabIndex:"-1",href:"#if-you-want-to-try-it",children:n(e.span,{className:"icon icon-link"})}),"If you want to try it"]}),`
`,n(e.p,{children:"My areas fit my life, and yours will look different. Maybe you barely travel but have three hobbies that each deserve an area of their own. The idea worth stealing is shelves and drawers: thinking about where something physically lives, not what it relates to or when you made it."}),`
`,n(e.p,{children:"I spent years tweaking systems instead of writing in them. This one is boring enough that I stopped fiddling with it."}),`
`,t(e.p,{children:["The ",n(e.a,{href:"https://johnnydecimal.com/10-19-concepts/11-core/11.06-saving-files/",children:"Saving Files"})," page on the Johnny Decimal site is where I'd start."]})]})}function d(i={}){const{wrapper:e}=i.components||{};return e?n(e,{...i,children:n(a,{...i})}):a(i)}export{d as default,s as toc};
